import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Module guides","description":"","frontmatter":{},"headers":[],"relativePath":"modules/index.md","filePath":"modules/README.md","lastUpdated":1790431304000}'),o={name:"modules/index.md"};function n(s,t,i,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="module-guides" tabindex="-1">Module guides <a class="header-anchor" href="#module-guides" aria-label="Permalink to &quot;Module guides&quot;">​</a></h1><p>Trustville is one town told in sixteen modules. Each one takes a trust problem an ordinary town actually has, builds the smallest honest contract that addresses it, and then says plainly what it did <strong>not</strong> fix.</p><p>You can read these in any order, but they are written to be read in sequence: later modules reuse the patterns earlier ones introduce, and several of them deliberately reuse an earlier module&#39;s <em>limitation</em> as the next module&#39;s problem.</p><h2 id="every-guide-has-the-same-shape" tabindex="-1">Every guide has the same shape <a class="header-anchor" href="#every-guide-has-the-same-shape" aria-label="Permalink to &quot;Every guide has the same shape&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What you get</th></tr></thead><tbody><tr><td><strong>The problem</strong></td><td>The everyday trust problem, stated without jargon</td></tr><tr><td><strong>The idea</strong></td><td>The one insight the module turns on</td></tr><tr><td><strong>Key terms</strong></td><td>The vocabulary, defined where you meet it</td></tr><tr><td><strong>How it works</strong></td><td>The data, the functions, who may call them</td></tr><tr><td><strong>The detail that matters</strong></td><td>The two or three lines that carry the design</td></tr><tr><td><strong>Walk through it</strong></td><td>What to do on <a href="https://dapp.didlab.org" target="_blank" rel="noreferrer">dapp.didlab.org</a>, in order</td></tr><tr><td><strong>What actually happened on chain</strong></td><td>The real events, and how to read them</td></tr><tr><td><strong>When a plain database is better</strong></td><td>Honest cases against using a blockchain at all</td></tr><tr><td><strong>What this does not fix</strong></td><td>The limitations, stated rather than hidden</td></tr><tr><td><strong>Common mistakes</strong></td><td>What goes wrong, including what went wrong here</td></tr><tr><td><strong>Security checklist</strong></td><td>Questions to ask before you deploy your own version</td></tr><tr><td><strong>Extend it</strong></td><td>Three or four exercises, each with a trap in it</td></tr><tr><td><strong>Further reading</strong></td><td>Standards, and one or two things worth reading properly</td></tr></tbody></table><h2 id="the-modules" tabindex="-1">The modules <a class="header-anchor" href="#the-modules" aria-label="Permalink to &quot;The modules&quot;">​</a></h2><h3 id="town-hall-—-identity-and-money" tabindex="-1">Town Hall — identity and money <a class="header-anchor" href="#town-hall-—-identity-and-money" aria-label="Permalink to &quot;Town Hall — identity and money&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-resident-record">Resident record</a></td><td><code>ResidentRegistry</code></td><td>Registry, hash anchoring</td></tr><tr><td>2</td><td><a href="./02-soulbound-passport">Soulbound Passport</a></td><td><code>TrustvillePassport</code></td><td>ERC-721 + ERC-5192</td></tr><tr><td>3</td><td><a href="./03-town-token">Town token</a></td><td><code>TownToken</code>, <code>TownBank</code></td><td>ERC-20</td></tr></tbody></table><h3 id="market-—-trade-between-strangers" tabindex="-1">Market — trade between strangers <a class="header-anchor" href="#market-—-trade-between-strangers" aria-label="Permalink to &quot;Market — trade between strangers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>4</td><td><a href="./04-product-provenance">Product provenance</a></td><td><code>ProductRegistry</code></td><td>Custody chain in events</td></tr><tr><td>5</td><td><a href="./05-escrow">Escrow</a></td><td><code>TownEscrow</code></td><td>State machine, arbitration</td></tr><tr><td>6</td><td><a href="./06-sealed-bid-auction">Sealed-bid auction</a></td><td><code>SealedAuction</code></td><td>Commit–reveal, pull payments</td></tr></tbody></table><h3 id="college-—-credentials-and-access" tabindex="-1">College — credentials and access <a class="header-anchor" href="#college-—-credentials-and-access" aria-label="Permalink to &quot;College — credentials and access&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>7</td><td><a href="./07-verifiable-certificates">Verifiable certificates</a></td><td><code>CertificateRegistry</code></td><td>W3C VC, simplified</td></tr><tr><td>8</td><td><a href="./08-event-tickets">Event tickets</a></td><td><code>EventTickets</code></td><td>ERC-1155</td></tr></tbody></table><h3 id="housing-—-property-and-deposits" tabindex="-1">Housing — property and deposits <a class="header-anchor" href="#housing-—-property-and-deposits" aria-label="Permalink to &quot;Housing — property and deposits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>9</td><td><a href="./09-property-deeds">Property deeds</a></td><td><code>PropertyDeeds</code></td><td>ERC-721 + transfer hook</td></tr><tr><td>10</td><td><a href="./10-rent-escrow">Rent escrow</a></td><td><code>RentEscrow</code></td><td>Two-asset state machine</td></tr></tbody></table><h3 id="council-—-collective-decisions" tabindex="-1">Council — collective decisions <a class="header-anchor" href="#council-—-collective-decisions" aria-label="Permalink to &quot;Council — collective decisions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>11</td><td><a href="./11-multisig-treasury">Multisig treasury</a></td><td><code>TownTreasury</code></td><td>M-of-N multisig</td></tr><tr><td>12</td><td><a href="./12-dao-governance">DAO governance</a></td><td><code>VoteToken</code>, <code>TownGovernor</code>, <code>TownTimelock</code></td><td>ERC-20Votes, ERC-6372, Governor</td></tr></tbody></table><h3 id="charity-insurer-exchange-—-money-with-conditions" tabindex="-1">Charity, Insurer, Exchange — money with conditions <a class="header-anchor" href="#charity-insurer-exchange-—-money-with-conditions" aria-label="Permalink to &quot;Charity, Insurer, Exchange — money with conditions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Guide</th><th>Contract</th><th>Standard or pattern</th></tr></thead><tbody><tr><td>13</td><td><a href="./13-charity">Charity</a></td><td><code>TownCharity</code></td><td>Milestone funding, pro-rata refunds</td></tr><tr><td>14</td><td><a href="./14-insurer">Insurer and oracle</a></td><td><code>RainOracle</code>, <code>CropInsurance</code></td><td>M-of-N oracle, parametric cover</td></tr><tr><td>15</td><td><a href="./15-defi">Swap and lending</a> ⚠</td><td><code>GrainToken</code>, <code>TownSwap</code>, <code>GrainLoans</code></td><td>Constant-product AMM, over-collateralised lending</td></tr></tbody></table><h3 id="still-to-come" tabindex="-1">Still to come <a class="header-anchor" href="#still-to-come" aria-label="Permalink to &quot;Still to come&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Module</th><th>Status</th></tr></thead><tbody><tr><td>16</td><td>Zero-knowledge proofs</td><td>Not yet built</td></tr></tbody></table><p>⚠ <strong>Module 15 contains a deliberate vulnerability.</strong> It is there to be exploited, and there is a test that exploits it. Read the guide before you read the contract.</p><h2 id="threads-that-run-through-the-whole-town" tabindex="-1">Threads that run through the whole town <a class="header-anchor" href="#threads-that-run-through-the-whole-town" aria-label="Permalink to &quot;Threads that run through the whole town&quot;">​</a></h2><p>Once you have read three or four guides you will start seeing the same ideas return. They are worth naming.</p><p><strong>Hash anchoring.</strong> Modules 1, 4, 7, 9 and 13 all put a <code>bytes32</code> on chain and keep the document off it. The chain proves integrity and timing; it never proves content, and it is the wrong place for personal data.</p><p><strong>Pull, never push.</strong> Modules 6, 8 and 13 record what they owe and let people withdraw. A contract that loops over addresses paying them out can be frozen for everyone by a single recipient who reverts.</p><p><strong>Checks, effects, interactions.</strong> Set your state before you call out. Modules 5, 6, 11 and 15 all depend on it, and module 11 explains what happens when you get it backwards.</p><p><strong>Time as a right.</strong> A deadline is not bookkeeping — it is the moment somebody gains a power they did not have. Modules 5, 6, 8, 10, 12 and 13 each turn on one, and in each case it is worth asking <em>whom</em> the clock protects.</p><p><strong>The oracle problem.</strong> Modules 4, 7, 13 and 14 are four attempts at the same question: how does a contract learn a fact about the world? None of them solves it. Module 14 is the most honest about that.</p><p><strong>Who decides.</strong> Almost every module ends up with a human somewhere — an arbiter, a certifier, a reporter, a voter. Trace where that person sits in each design, and what they can and cannot do. That is usually the real security model.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Live town: <a href="https://dapp.didlab.org" target="_blank" rel="noreferrer">dapp.didlab.org</a></li><li>Explorer: <a href="https://explorer.didlab.org" target="_blank" rel="noreferrer">explorer.didlab.org</a></li><li>Chain: DIDLab, chain id <strong>252501</strong>, RPC <code>https://eth.didlab.org</code>, native token TRUST</li><li>You need MetaMask, a little TRUST for gas, and to register in module 1 before most of the rest will let you do anything.</li></ul><p>Running the whole town locally, with no MetaMask and no TRUST needed, takes one command — see the <a href="https://github.com/touidhasan/didlab-trustville#readme" target="_blank" rel="noreferrer">repository README</a>.</p><h2 id="labs" tabindex="-1">Labs <a class="header-anchor" href="#labs" aria-label="Permalink to &quot;Labs&quot;">​</a></h2><p>The guides explain the town. The <a href="./../labs/">labs</a> are the graded work: shipping a change, reading the chain, writing transactions, a vertical slice, state machines and time, and finally money, prices and failure. They assume you have read the guide for the module they touch.</p>',34)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
